"""由Blender MCP执行的A1样区烘焙：独立UV2、AO与无底色间接光，不替换主场景。"""
import argparse,hashlib,json,math,time
from pathlib import Path
import bpy
from mathutils import Vector

ROOT=Path('__PROJECT_ROOT__')
PLAN=json.loads((ROOT/'planning/project.json').read_text())
CFG=PLAN['production']['bakingPilot']
OUT=ROOT/CFG['outputDirectory'];OUT.mkdir(parents=True,exist_ok=True)

def record(stage,**kwargs):
 payload={'stage':stage,'planningSha256':hashlib.sha256((ROOT/'planning/project.json').read_bytes()).hexdigest(),**kwargs}
 (OUT/'job.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps(payload,ensure_ascii=False))

def export():
 # 用glTF标准遮蔽节点导出AO；间接光由网页以UV2独立接入，避免错误烘进BaseColor。
 group=bpy.data.node_groups.get('glTF Material Output') or bpy.data.node_groups.new('glTF Material Output','ShaderNodeTree')
 if not any(i.name=='Occlusion' for i in group.interface.items_tree):group.interface.new_socket(name='Occlusion',in_out='INPUT',socket_type='NodeSocketFloat')
 ao_image=bpy.data.images.load(str(OUT/'ao.png'),check_existing=False);ao_image.colorspace_settings.name='Non-Color'
 for name in CFG['receivers']:
  for mat in bpy.data.objects[name].data.materials:
   nodes=mat.node_tree.nodes
   for node in list(nodes):
    if node.name=='BakeTarget' or (node.type=='GROUP' and node.node_tree==group) or (node.type=='UVMAP' and node.uv_map==CFG['uvLayer']) or (node.type=='TEX_IMAGE' and node.image and node.image.filepath.endswith('/ao.png')):nodes.remove(node)
   uv=nodes.new('ShaderNodeUVMap');uv.uv_map=CFG['uvLayer']
   tex=nodes.new('ShaderNodeTexImage');tex.image=ao_image;mat.node_tree.links.new(uv.outputs['UV'],tex.inputs['Vector'])
   out=nodes.new('ShaderNodeGroup');out.node_tree=group;mat.node_tree.links.new(tex.outputs['Color'],out.inputs['Occlusion'])
 for obj in bpy.data.objects:
  if obj.type=='MESH':obj.hide_render=False
 original=bpy.data.meshes.get('_unbaked_people_original')
 if original:bpy.data.objects['landscape_stone'].data=original
 # 不导出烘焙辅助灯具和相机；完整几何保留原业务ID及拾取身份。
 for image in list(bpy.data.images):
  if image.users==0 and image.type!='RENDER_RESULT':bpy.data.images.remove(image)
  elif image.users>0 and image.type!='RENDER_RESULT':image.pack()
 bpy.ops.wm.save_as_mainfile(filepath=str(OUT/'pilot-baked.blend'))
 bpy.ops.export_scene.gltf(filepath=str(OUT/'pilot.glb'),export_format='GLB',export_yup=True,export_extras=True,export_cameras=False,export_lights=False,export_apply=True)
 files={n:{'bytes':(OUT/n).stat().st_size,'sha256':hashlib.sha256((OUT/n).read_bytes()).hexdigest()} for n in ['pilot.glb','ao.png','indirect.png','indirect.exr','pilot-baked.blend']}
 manifest={'version':CFG['version'],'scope':'A1裙房及广场烘焙技术样区；不是三场景最终还原或验收','planningSha256':hashlib.sha256((ROOT/'planning/project.json').read_bytes()).hexdigest(),'execution':'Blender MCP execute_blender_code','receivers':CFG['receivers'],'aoStrength':CFG['aoStrength'],'indirectStrength':CFG['indirectStrength'],'uvChannel':CFG['uvChannel'],'files':files}
 (OUT/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
 record('exported',files=files)


export()
